with parsed as (select id, service, host, log_ts, payload_json, context, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier, coalesce(context['region'], 'direct') as region_or_default, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec from app_logs where host in ('h3', 'h1')) select id, service, log_ts, tier, region_or_default, duration_sec, first_value(region_or_default, true) over (partition by service order by log_ts, id rows between unbounded preceding and current row) first_known_region_or_default, avg(duration_sec) over (partition by date_trunc('YEAR', log_ts), tier order by duration_sec, id rows between 6 preceding and 1 preceding) duration_sec_avg_6_prior, avg(duration_sec) over (partition by service, host) service_avg_duration_sec, percent_rank() over (partition by tier order by duration_sec) duration_sec_percent_rank, ntile(10) over (partition by to_date(log_ts), service order by duration_sec, id) duration_sec_bucket from parsed
